window.BAHR_DATA=window.BAHR_DATA||{};window.BAHR_DATA["passages-095"]=[{"id":"K095.01","q":"95:1–8","s":95,"surah":"al-Tīn","surah_ar":"التين","title":"al-Tīn · Heading and verses","cairo":"K IV:773–774 · T XVI:504–508","source_page_first":773,"source_page_last":774,"chunk":"passages-095","segments":[{"type":"exposition","title":"Heading and verses [IV:773]","html":"<p>Meccan; eight verses. [The DKA heading additionally places its revelation after al-Burūj.]\nIn the name of God, the All-Merciful, the Merciful.</p><p>By the fig and the olive, (1) and Mount Sīnīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(سينين)</bdi>, (2) and this secure city: (3) We have indeed created the human being in the finest proportion; (4) then We returned him to the lowest of the low, (5) except those who believe and do righteous deeds: theirs is a reward unceasing. (6) So what makes you deny the requital after this? (7) Is God not the wisest of judges? (8)</p>","author":"kashshaf","source_id":"K095.01"}],"types":["exposition","language","theology","reports"],"ar":"مكية، وآياتها 8 [نزلت بعد البروج] بسم الله الرحمن الرحيم\nبسم الله الرحمن الرحيم\nوالتين والزيتون (1) وطور سينين (2) وهذا البلد الأمين (3) لقد خلقنا الإنسان في أحسن تقويم (4)\nثم رددناه أسفل سافلين (5) إلا الذين آمنوا وعملوا الصالحات فلهم أجر غير ممنون (6) فما يكذبك بعد بالدين (7) أليس الله بأحكم الحاكمين (8)","layers":[{"id":"K095.01","heading":"K095.01 — Heading and verses [IV:773]","text":"Meccan; eight verses. [The DKA heading additionally places its revelation after al-Burūj.]\nIn the name of God, the All-Merciful, the Merciful.\n\nBy the fig and the olive, (1) and Mount Sīnīn, (2) and this secure city: (3) We have indeed created the human being in the finest proportion; (4) then We returned him to the lowest of the low, (5) except those who believe and do righteous deeds: theirs is a reward unceasing. (6) So what makes you deny the requital after this? (7) Is God not the wisest of judges? (8)","title":"Heading and verses [IV:773]","author":"kashshaf","surah":95,"ar":"مكية، وآياتها 8 [نزلت بعد البروج] بسم الله الرحمن الرحيم\n\nبسم الله الرحمن الرحيم\n\nوالتين والزيتون (1) وطور سينين (2) وهذا البلد الأمين (3) لقد خلقنا الإنسان في أحسن تقويم (4)\n\nثم رددناه أسفل سافلين (5) إلا الذين آمنوا وعملوا الصالحات فلهم أجر غير ممنون (6) فما يكذبك بعد بالدين (7) أليس الله بأحكم الحاكمين (8)","html":"<p>Meccan; eight verses. [The DKA heading additionally places its revelation after al-Burūj.]\nIn the name of God, the All-Merciful, the Merciful.</p><p>By the fig and the olive, (1) and Mount Sīnīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(سينين)</bdi>, (2) and this secure city: (3) We have indeed created the human being in the finest proportion; (4) then We returned him to the lowest of the low, (5) except those who believe and do righteous deeds: theirs is a reward unceasing. (6) So what makes you deny the requital after this? (7) Is God not the wisest of judges? (8)</p>","lemma":""}],"cairo_notes":[],"verses":[{"key":"95:1","number":1,"ar":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ","en":"By the fig and the olive"},{"key":"95:2","number":2,"ar":"وَطُورِ سِينِينَ","en":"By Mount Sinai"},{"key":"95:3","number":3,"ar":"وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","en":"And by this land made safe"},{"key":"95:4","number":4,"ar":"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ","en":"Surely We created man of the best stature"},{"key":"95:5","number":5,"ar":"ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ","en":"Then we reduced him to the lowest of the low"},{"key":"95:6","number":6,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ","en":"Save those who believe and do good works, and theirs is a reward unfailing"},{"key":"95:7","number":7,"ar":"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","en":"So who henceforth will give the lie to thee about the judgment"},{"key":"95:8","number":8,"ar":"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ","en":"Is not Allah the most conclusive of all judges"}],"quran_ar":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ ﴿1﴾ وَطُورِ سِينِينَ ﴿2﴾ وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ ﴿3﴾ لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ ﴿4﴾ ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ ﴿5﴾ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ ﴿6﴾ فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ ﴿7﴾ أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ ﴿8﴾","quran_en":"1. By the fig and the olive 2. By Mount Sinai 3. And by this land made safe 4. Surely We created man of the best stature 5. Then we reduced him to the lowest of the low 6. Save those who believe and do good works, and theirs is a reward unfailing 7. So who henceforth will give the lie to thee about the judgment 8. Is not Allah the most conclusive of all judges"},{"id":"K095.02","q":"95:1","s":95,"surah":"al-Tīn","surah_ar":"التين","title":"al-Tīn · The fig and olive","cairo":"K IV:773–774 · T XVI:504–508","source_page_first":773,"source_page_last":774,"chunk":"passages-095","segments":[{"type":"exposition","title":"The fig and olive [IV:773]","html":"<p>He swears by these two because they are remarkable among the varieties of fruit-bearing trees. It is related that a dish of figs was presented to God’s Messenger. He ate some and said to his companions: “Eat! If I were to say that a fruit had descended from Paradise, I would say it was this one, because the fruit of Paradise has no stones. So eat them: they stop haemorrhoids and help against gout.”</p><p>Muʿādh ibn Jabal passed an olive tree, took a twig from it, and cleaned his teeth with it. He said: “I heard God’s Messenger say, ‘What an excellent tooth-stick is the olive, from the blessed tree! It sweetens the mouth and removes decay.’ And I heard him say, ‘It is my tooth-stick and the tooth-stick of the prophets before me.’” From Ibn ʿAbbās: “It is this fig of yours and this olive of yours.”</p><p>It is also said that they are two mountains of the Holy Land called in Syriac Ṭūr <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(طور)</bdi> Tīnā and Ṭūr <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(طور)</bdi> Zaytā, because they are places where figs and olives grow. Another view makes “the fig” the mountains between Ḥulwān and Hamadhān, and “the olive” the mountains of Syria, because these fruits grow there: as though He said, “By the places where figs and olives grow.”</p>","author":"kashshaf","source_id":"K095.02"},{"type":"exposition","title":"Fruit-stones and the properties of figs and olives [XVI:504–505]","html":"<p>Meccan; eight verses. In the name of God, the All-Merciful, the Merciful.</p><p>On “without stones”: it is transmitted both with a quiescent jīm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(جيم (ج))</bdi>, ʿajm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجْم)</bdi>, and with fatḥa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(فَتْحَة (ـَ))</bdi>, ʿajam <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجَم)</bdi>. Dīwān al-Adab has: “ʿAjam <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجَم)</bdi>, with the middle consonant vowelled, means fruit-stones”; it does not list ʿajm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجْم)</bdi> in this sense. Al-Jawharī says: “Ordinary people say ʿajm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجْم)</bdi>, with the jīm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(جيم (ج))</bdi> quiescent.”</p><p>On “they stop haemorrhoids,” the Qāḍī [al-Bayḍāwī] says: “The fig is a pleasant fruit with no waste. As food it is light and quickly digested, and as a medicine it has many benefits: it loosens the bowels, dissolves phlegm, cleanses the kidneys, removes gravel from the bladder, opens obstructions of the liver and spleen, and fattens the body. The olive is a fruit, a condiment, and a medicine. Its oil is light, very beneficial, and pleasant; yet it sometimes grows where it contains no oil, as in the mountains.”</p>","author":"tibi","source_id":"T095.01"}],"types":["exposition","language","theology","reports"],"ar":"أقسم بهما لأنهما عجيبان من بين أصناف الأشجار المثمرة، وروى أنه أهدى لرسول الله صلى الله عليه وسلم طبق من تين فأكل منه وقال لأصحابه: «كلوا، فلو قلت إن فاكهة نزلت من الجنة لقلت هذه، لأن فاكهة الجنة بلا عجم، فكلوها. فإنها تقطع البواسير وتنفع من النقرس» ومر معاذ بن جبل بشجرة الزيتون فأخذ منها قضيبا واستاك به وقال: سمعت رسول الله صلى الله عليه وسلم يقول «نعم السواك الزيتون من الشجرة المباركة يطيب الفم ويذهب بالحفرة » وسمعته يقول «هي سواكي وسواك الأنبياء قبلي» وعن ابن عباس رضى الله عنه: هو تينكم هذا وزيتونكم. وقيل: جبلان من الأرض المقدسة يقال لهما بالسريانية: طور تينا وطور زيتا، لأنهما منبتا التين والزيتون. وقيل «التين» جبال ما بين حلوان وهمدان. و «الزيتون» جبال الشام، لأنها منابتهما، كأنه قيل: ومنابت التين والزيتون.\nمكية، وهي ثماني آيات\nبسم الله الرحمن الرحيم\nقوله: (بلا عجم)، يروى بسكون الجيم وبفتحها. وفي \"ديوان الأدب\": \"العجم بالتحريك: النوى\"، وليس في عجم بهذا المعنى.\nالجوهري: \"العامة تقول: عجم، بالتسكين\".\nقوله: (فإنها تقطع البواسير)، قال القاضي: \"التين فاكهة طيبة لا فضل له، وعند الغذاء لطيف سريع الهضم، ودواء كثير النفع، فإنه يلين الطبع، ويحل البلغم، ويطهر الكليتين، ويزيل رمل المثانة، ويفتح سدة الكبد والطحال، ويسمن البدن. والزيتون فاكهة وإدام ودواء، وله دهن لطيف كثير المنافع مع لذته، لكنه قد ينبت حيث لا دهنية فيه كالجبال\".","layers":[{"id":"K095.02","heading":"K095.02 — The fig and olive [IV:773]","text":"He swears by these two because they are remarkable among the varieties of fruit-bearing trees. It is related that a dish of figs was presented to God’s Messenger. He ate some and said to his companions: “Eat! If I were to say that a fruit had descended from Paradise, I would say it was this one, because the fruit of Paradise has no stones. So eat them: they stop haemorrhoids and help against gout.”\n\nMuʿādh ibn Jabal passed an olive tree, took a twig from it, and cleaned his teeth with it. He said: “I heard God’s Messenger say, ‘What an excellent tooth-stick is the olive, from the blessed tree! It sweetens the mouth and removes decay.’ And I heard him say, ‘It is my tooth-stick and the tooth-stick of the prophets before me.’” From Ibn ʿAbbās: “It is this fig of yours and this olive of yours.”\n\nIt is also said that they are two mountains of the Holy Land called in Syriac Ṭūr Tīnā and Ṭūr Zaytā, because they are places where figs and olives grow. Another view makes “the fig” the mountains between Ḥulwān and Hamadhān, and “the olive” the mountains of Syria, because these fruits grow there: as though He said, “By the places where figs and olives grow.”","title":"The fig and olive [IV:773]","author":"kashshaf","surah":95,"ar":"أقسم بهما لأنهما عجيبان من بين أصناف الأشجار المثمرة، وروى أنه أهدى لرسول الله صلى الله عليه وسلم طبق من تين فأكل منه وقال لأصحابه: «كلوا، فلو قلت إن فاكهة نزلت من الجنة لقلت هذه، لأن فاكهة الجنة بلا عجم، فكلوها. فإنها تقطع البواسير وتنفع من النقرس» ومر معاذ بن جبل بشجرة الزيتون فأخذ منها قضيبا واستاك به وقال: سمعت رسول الله صلى الله عليه وسلم يقول «نعم السواك الزيتون من الشجرة المباركة يطيب الفم ويذهب بالحفرة » وسمعته يقول «هي سواكي وسواك الأنبياء قبلي» وعن ابن عباس رضى الله عنه: هو تينكم هذا وزيتونكم. وقيل: جبلان من الأرض المقدسة يقال لهما بالسريانية: طور تينا وطور زيتا، لأنهما منبتا التين والزيتون. وقيل «التين» جبال ما بين حلوان وهمدان. و «الزيتون» جبال الشام، لأنها منابتهما، كأنه قيل: ومنابت التين والزيتون.","html":"<p>He swears by these two because they are remarkable among the varieties of fruit-bearing trees. It is related that a dish of figs was presented to God’s Messenger. He ate some and said to his companions: “Eat! If I were to say that a fruit had descended from Paradise, I would say it was this one, because the fruit of Paradise has no stones. So eat them: they stop haemorrhoids and help against gout.”</p><p>Muʿādh ibn Jabal passed an olive tree, took a twig from it, and cleaned his teeth with it. He said: “I heard God’s Messenger say, ‘What an excellent tooth-stick is the olive, from the blessed tree! It sweetens the mouth and removes decay.’ And I heard him say, ‘It is my tooth-stick and the tooth-stick of the prophets before me.’” From Ibn ʿAbbās: “It is this fig of yours and this olive of yours.”</p><p>It is also said that they are two mountains of the Holy Land called in Syriac Ṭūr <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(طور)</bdi> Tīnā and Ṭūr <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(طور)</bdi> Zaytā, because they are places where figs and olives grow. Another view makes “the fig” the mountains between Ḥulwān and Hamadhān, and “the olive” the mountains of Syria, because these fruits grow there: as though He said, “By the places where figs and olives grow.”</p>","lemma":""},{"id":"T095.01","heading":"T095.01 — Fruit-stones and the properties of figs and olives [XVI:504–505]","text":"Meccan; eight verses. In the name of God, the All-Merciful, the Merciful.\n\nOn “without stones”: it is transmitted both with a quiescent jīm, ʿajm, and with fatḥa, ʿajam. Dīwān al-Adab has: “ʿAjam, with the middle consonant vowelled, means fruit-stones”; it does not list ʿajm in this sense. Al-Jawharī says: “Ordinary people say ʿajm, with the jīm quiescent.”\n\nOn “they stop haemorrhoids,” the Qāḍī [al-Bayḍāwī] says: “The fig is a pleasant fruit with no waste. As food it is light and quickly digested, and as a medicine it has many benefits: it loosens the bowels, dissolves phlegm, cleanses the kidneys, removes gravel from the bladder, opens obstructions of the liver and spleen, and fattens the body. The olive is a fruit, a condiment, and a medicine. Its oil is light, very beneficial, and pleasant; yet it sometimes grows where it contains no oil, as in the mountains.”","title":"Fruit-stones and the properties of figs and olives [XVI:504–505]","author":"tibi","on":["K095.02"],"anchor":"K095.02","surah":95,"ar":"مكية، وهي ثماني آيات\n\nبسم الله الرحمن الرحيم\n\nقوله: (بلا عجم)، يروى بسكون الجيم وبفتحها. وفي \"ديوان الأدب\": \"العجم بالتحريك: النوى\"، وليس في عجم بهذا المعنى.\n\nالجوهري: \"العامة تقول: عجم، بالتسكين\".\n\nقوله: (فإنها تقطع البواسير)، قال القاضي: \"التين فاكهة طيبة لا فضل له، وعند الغذاء لطيف سريع الهضم، ودواء كثير النفع، فإنه يلين الطبع، ويحل البلغم، ويطهر الكليتين، ويزيل رمل المثانة، ويفتح سدة الكبد والطحال، ويسمن البدن. والزيتون فاكهة وإدام ودواء، وله دهن لطيف كثير المنافع مع لذته، لكنه قد ينبت حيث لا دهنية فيه كالجبال\".","html":"<p>Meccan; eight verses. In the name of God, the All-Merciful, the Merciful.</p><p>On “without stones”: it is transmitted both with a quiescent jīm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(جيم (ج))</bdi>, ʿajm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجْم)</bdi>, and with fatḥa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(فَتْحَة (ـَ))</bdi>, ʿajam <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجَم)</bdi>. Dīwān al-Adab has: “ʿAjam <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجَم)</bdi>, with the middle consonant vowelled, means fruit-stones”; it does not list ʿajm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجْم)</bdi> in this sense. Al-Jawharī says: “Ordinary people say ʿajm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(عَجْم)</bdi>, with the jīm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(جيم (ج))</bdi> quiescent.”</p><p>On “they stop haemorrhoids,” the Qāḍī [al-Bayḍāwī] says: “The fig is a pleasant fruit with no waste. As food it is light and quickly digested, and as a medicine it has many benefits: it loosens the bowels, dissolves phlegm, cleanses the kidneys, removes gravel from the bladder, opens obstructions of the liver and spleen, and fattens the body. The olive is a fruit, a condiment, and a medicine. Its oil is light, very beneficial, and pleasant; yet it sometimes grows where it contains no oil, as in the mountains.”</p>","lemma":"بلا عجم"}],"cairo_notes":[],"verses":[{"key":"95:1","number":1,"ar":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ","en":"By the fig and the olive"}],"quran_ar":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ ﴿1﴾","quran_en":"1. By the fig and the olive"},{"id":"K095.03","q":"95:2–3","s":95,"surah":"al-Tīn","surah_ar":"التين","title":"al-Tīn · Sīnīn, the secure city, and the blessed places","cairo":"K IV:773–774 · T XVI:504–508","source_page_first":773,"source_page_last":774,"chunk":"passages-095","segments":[{"type":"exposition","title":"Sīnīn, the secure city, and the blessed places [IV:773–774]","html":"<p>Al-ṭūr, “the mountain,” is put in a genitive construction with Sīnīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(سينين)</bdi>, which is the locality. Sīnūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(سينون)</bdi> resembles Yabrūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(يبرون)</bdi> in permitting declension with wāw <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(واو (و))</bdi> and yāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ياء (ي))</bdi>, or retention of the yāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ياء (ي))</bdi> while the nūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(نون (ن))</bdi> takes the case vowels.</p><p>“The city” is Mecca—may God protect it. Amīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمين)</bdi> derives from amuna al-rajulu amānatan <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمانة)</bdi> fa-huwa amīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمين)</bdi>, “the man proved trustworthy, and so is trustworthy.” Ammān <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمّان)</bdi> is also said, just as karrām <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(كرّام)</bdi> is used for karīm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(كريم)</bdi>. Its trustworthiness consists in protecting whoever enters it, as a trustworthy person protects what is entrusted to him. It may also be a faʿīl <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(فعيل)</bdi> form with a passive sense, from aminahu, since the city is secure from calamities. Thus it is described as secure in His saying, “a secure sanctuary” [28:57], meaning one possessing security.</p><p>The purpose of swearing by these things is to disclose the honour of the blessed places, and the good and blessing manifested there through the residence of prophets and righteous people. The place where figs and olives grow is Abraham’s place of migration and Jesus’ birthplace and place of upbringing. The Mount is the place from which Moses was called. Mecca is the location of the House that is guidance for all peoples, and God’s Messenger’s birthplace and the place of his commissioning.</p>","author":"kashshaf","source_id":"K095.03"},{"type":"exposition","title":"Tooth decay and trustworthy places [XVI:505]","html":"<p>On “removes decay”: one says ḥafirat asnānuhu ḥafaran <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(حَفِرَت أسنانه حَفَرًا)</bdi> when the sockets of his teeth—that is, their roots—have deteriorated. One also says ḥafarat ḥafran <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(حَفَرَت حَفْرًا)</bdi>; ḥafra <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(حَفْرة)</bdi> denotes a single occurrence.</p><p>On “and so is amīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمين)</bdi>; ammān <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمّان)</bdi> is also said”: that is, they say, “in a trustworthy place.”</p>","author":"tibi","source_id":"T095.02"}],"types":["exposition","language","theology","reports"],"ar":"وأضيف الطور: وهو الجبل، إلى سينين: وهي البقعة. ونحو سينون: يبرون، في جواز الإعراب بالواو والياء، والإقرار على الياء، وتحريك النون بحركات الإعراب. وللبلد: مكة حماها الله. والأمين: من أمن الرجل أمانة فهو أمين. وقيل: أمان، كما قيل: كرام في كريم. وأمانته: أن يحفظ من دخله كما يحفظ الأمين ما يؤتمن عليه. ويجوز أن يكون فعيلا بمعنى مفعول، من أمنه لأنه مأمون الغوائل، \nكما وصف بالأمن في قوله تعالى حرما آمنا بمعنى: ذى أمن. ومعى القسم بهذه الأشياء.\nالإبانة عن شرف البقاع المباركة وما ظهر فيها من الخير والبركة بسكنى الأنبياء والصالحين، فمنبت التين والزيتون مهاجر إبراهيم ومولد عيسى ومنشؤه. والطور: المكان الذي نودي منه موسى. ومكة: مكان البيت الذي هو هدى للعالمين، ومولد رسول الله صلى الله عليه وسلم ومبعثه\nقوله: (ويذهب بالحفرة)، يقال: حفرت أسنانه حفرا إذا فسد أسناخها، أي: أصولها، ويقال أيضا: حفرت حفرا، والحفرة للمرة.\nقوله: (فهو أمين، وقيل: أمان)، أي: قالوا: في موضع أمين.","layers":[{"id":"K095.03","heading":"K095.03 — Sīnīn, the secure city, and the blessed places [IV:773–774]","text":"Al-ṭūr, “the mountain,” is put in a genitive construction with Sīnīn, which is the locality. Sīnūn resembles Yabrūn in permitting declension with wāw and yāʾ, or retention of the yāʾ while the nūn takes the case vowels.\n\n“The city” is Mecca—may God protect it. Amīn derives from amuna al-rajulu amānatan fa-huwa amīn, “the man proved trustworthy, and so is trustworthy.” Ammān is also said, just as karrām is used for karīm. Its trustworthiness consists in protecting whoever enters it, as a trustworthy person protects what is entrusted to him. It may also be a faʿīl form with a passive sense, from aminahu, since the city is secure from calamities. Thus it is described as secure in His saying, “a secure sanctuary” [28:57], meaning one possessing security.\n\nThe purpose of swearing by these things is to disclose the honour of the blessed places, and the good and blessing manifested there through the residence of prophets and righteous people. The place where figs and olives grow is Abraham’s place of migration and Jesus’ birthplace and place of upbringing. The Mount is the place from which Moses was called. Mecca is the location of the House that is guidance for all peoples, and God’s Messenger’s birthplace and the place of his commissioning.","title":"Sīnīn, the secure city, and the blessed places [IV:773–774]","author":"kashshaf","surah":95,"ar":"وأضيف الطور: وهو الجبل، إلى سينين: وهي البقعة. ونحو سينون: يبرون، في جواز الإعراب بالواو والياء، والإقرار على الياء، وتحريك النون بحركات الإعراب. وللبلد: مكة حماها الله. والأمين: من أمن الرجل أمانة فهو أمين. وقيل: أمان، كما قيل: كرام في كريم. وأمانته: أن يحفظ من دخله كما يحفظ الأمين ما يؤتمن عليه. ويجوز أن يكون فعيلا بمعنى مفعول، من أمنه لأنه مأمون الغوائل، \n\nكما وصف بالأمن في قوله تعالى حرما آمنا بمعنى: ذى أمن. ومعى القسم بهذه الأشياء.\n\nالإبانة عن شرف البقاع المباركة وما ظهر فيها من الخير والبركة بسكنى الأنبياء والصالحين، فمنبت التين والزيتون مهاجر إبراهيم ومولد عيسى ومنشؤه. والطور: المكان الذي نودي منه موسى. ومكة: مكان البيت الذي هو هدى للعالمين، ومولد رسول الله صلى الله عليه وسلم ومبعثه","html":"<p>Al-ṭūr, “the mountain,” is put in a genitive construction with Sīnīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(سينين)</bdi>, which is the locality. Sīnūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(سينون)</bdi> resembles Yabrūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(يبرون)</bdi> in permitting declension with wāw <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(واو (و))</bdi> and yāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ياء (ي))</bdi>, or retention of the yāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ياء (ي))</bdi> while the nūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(نون (ن))</bdi> takes the case vowels.</p><p>“The city” is Mecca—may God protect it. Amīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمين)</bdi> derives from amuna al-rajulu amānatan <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمانة)</bdi> fa-huwa amīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمين)</bdi>, “the man proved trustworthy, and so is trustworthy.” Ammān <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمّان)</bdi> is also said, just as karrām <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(كرّام)</bdi> is used for karīm <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(كريم)</bdi>. Its trustworthiness consists in protecting whoever enters it, as a trustworthy person protects what is entrusted to him. It may also be a faʿīl <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(فعيل)</bdi> form with a passive sense, from aminahu, since the city is secure from calamities. Thus it is described as secure in His saying, “a secure sanctuary” [28:57], meaning one possessing security.</p><p>The purpose of swearing by these things is to disclose the honour of the blessed places, and the good and blessing manifested there through the residence of prophets and righteous people. The place where figs and olives grow is Abraham’s place of migration and Jesus’ birthplace and place of upbringing. The Mount is the place from which Moses was called. Mecca is the location of the House that is guidance for all peoples, and God’s Messenger’s birthplace and the place of his commissioning.</p>","lemma":""},{"id":"T095.02","heading":"T095.02 — Tooth decay and trustworthy places [XVI:505]","text":"On “removes decay”: one says ḥafirat asnānuhu ḥafaran when the sockets of his teeth—that is, their roots—have deteriorated. One also says ḥafarat ḥafran; ḥafra denotes a single occurrence.\n\nOn “and so is amīn; ammān is also said”: that is, they say, “in a trustworthy place.”","title":"Tooth decay and trustworthy places [XVI:505]","author":"tibi","on":["K095.02","K095.03"],"anchor":"K095.03","surah":95,"ar":"قوله: (ويذهب بالحفرة)، يقال: حفرت أسنانه حفرا إذا فسد أسناخها، أي: أصولها، ويقال أيضا: حفرت حفرا، والحفرة للمرة.\n\nقوله: (فهو أمين، وقيل: أمان)، أي: قالوا: في موضع أمين.","html":"<p>On “removes decay”: one says ḥafirat asnānuhu ḥafaran <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(حَفِرَت أسنانه حَفَرًا)</bdi> when the sockets of his teeth—that is, their roots—have deteriorated. One also says ḥafarat ḥafran <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(حَفَرَت حَفْرًا)</bdi>; ḥafra <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(حَفْرة)</bdi> denotes a single occurrence.</p><p>On “and so is amīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمين)</bdi>; ammān <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أمّان)</bdi> is also said”: that is, they say, “in a trustworthy place.”</p>","lemma":"ويذهب بالحفرة"}],"cairo_notes":[],"verses":[{"key":"95:2","number":2,"ar":"وَطُورِ سِينِينَ","en":"By Mount Sinai"},{"key":"95:3","number":3,"ar":"وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","en":"And by this land made safe"}],"quran_ar":"وَطُورِ سِينِينَ ﴿2﴾ وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ ﴿3﴾","quran_en":"2. By Mount Sinai 3. And by this land made safe"},{"id":"K095.04","q":"95:4–5","s":95,"surah":"al-Tīn","surah_ar":"التين","title":"al-Tīn · Finest proportion and the lowest condition","cairo":"K IV:773–774 · T XVI:504–508","source_page_first":773,"source_page_last":774,"chunk":"passages-095","segments":[{"type":"exposition","title":"Finest proportion and the lowest condition [IV:774]","html":"<p>“In the finest proportion”: in the finest adjustment of his shape and form, and the most harmonious arrangement of his limbs. Then, when he failed to give thanks for the blessing of that beautiful, upright, well-proportioned creation, his final outcome was that We returned him lower than those low in constitution and composition: uglier in form than the ugly, and most deformed in creation. These are the inhabitants of the Fire. Or: lower than the lowest inhabitants of its descending levels.</p><p>Or: after that proportioning and beautification, We returned him lower than those lowest in beauty of form and shape, reversing his constitution. His back, once straight, became bent; his hair, once black, turned white; his skin, once tender, dried and wrinkled; his hearing and sight, once sharp, grew dull. Everything about him changed: his gait became shuffling, his voice faint, his strength weakness, and his mental alertness senility.</p><p>ʿAbd Allāh <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(الله)</bdi> [ibn Masʿūd] read asfala al-sāfilīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(السافلين)</bdi>, with the definite article: “the lowest of the low.”</p>","author":"kashshaf","source_id":"K095.04"},{"type":"exposition","title":"The vocabulary of ageing [XVI:506]","html":"<p>On “dried and wrinkled,” al-Asās says: “Tashannana jilduhu min al-haram <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(تشنّن جلده من الهرم)</bdi> means his skin shrivelled and dried from old age. One says, ‘an old man like a worn-out waterskin.’”</p><p>On “tender,” baḍḍ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(بَضّ)</bdi>, with the single-dotted bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> and dotted ḍād <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ضاد (ض))</bdi>: al-Asās says: “Al-Aṣmaʿī said: abyaḍ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أبيض)</bdi> baḍḍ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(بَضّ)</bdi> means intensely white. Al-Mubarrad said: it means a person with fine skin on which everything leaves an impression. One says imraʾa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(امرأة)</bdi> ghaḍḍa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(غَضّة)</bdi> baḍḍa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(بَضّة)</bdi>, a fresh, tender-skinned woman.”</p><p>On “his gait became shuffling”: dalīf <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(دليف)</bdi> is slow walking. Al-Asās says: “The old man and the fettered man dalafa dalīfan <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(دليفًا)</bdi> wa-dulūfan <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ودلوفًا)</bdi>; this is a little more than creeping.”</p><p>On “senility”: kharaf, with the middle consonant vowelled, means deterioration of the mind.</p>","author":"tibi","source_id":"T095.03"}],"types":["exposition","language","theology","reports"],"ar":"في أحسن تقويم في أحسن تعديل لشكله وصورته وتسوية لأعضائه. ثم كان عاقبة أمره حين لم يشكر نعمة تلك الخلقة الحسنة القويمة السوية: أن رددناه أسفل من سفل خلقا وتركيبا، يعنى: أقبح من قبح صورة وأشوهه خلقة، وهم أصحاب النار أو أسفل من سفل من أهل الدركات. أو ثم رددناه بعد ذلك التقويم والتحسين أسفل من سفل في حسن الصورة والشكل: حيث نكسناه في خلقه، فقوس ظهره بعد اعتداله، وابيض شعره بعد سواده، وتشنن جلده وكان بضا، وكل سمعه وبصره وكانا حديدين، وتغير كل شيء منه: فمشيه دليف ، وصوته خفات، وقوته ضعف، وشهامته خرف وقرأ عبد الله:\nأسفل السافلين.\nقوله: (تشنن)، الأساس: \"تشنن جلده من الهرم، أي: تشنج ويبس. ويقال: شيخ كالشن البالي\".\nقوله: (بضا)، بالباء الموحدة من تحت والضاد المعجمة. الأساس: \"قال الأصمعي: أبيض بض. وهو الشديد البياض. وقال المبرد: هو الرقيق البشرة الذي يؤثر فيه كل شيء. وامرأة غضة بضة\".\nقوله: (فمشيه دليف)، الدليف: المشي الرويد. الأساس: \"دلف الشيخ والمقيد دليفا ودلوفا، وهو فوق الدبيب\".\nقوله: (خرف)، الخرف بالتحريك: فساد العقل.","layers":[{"id":"K095.04","heading":"K095.04 — Finest proportion and the lowest condition [IV:774]","text":"“In the finest proportion”: in the finest adjustment of his shape and form, and the most harmonious arrangement of his limbs. Then, when he failed to give thanks for the blessing of that beautiful, upright, well-proportioned creation, his final outcome was that We returned him lower than those low in constitution and composition: uglier in form than the ugly, and most deformed in creation. These are the inhabitants of the Fire. Or: lower than the lowest inhabitants of its descending levels.\n\nOr: after that proportioning and beautification, We returned him lower than those lowest in beauty of form and shape, reversing his constitution. His back, once straight, became bent; his hair, once black, turned white; his skin, once tender, dried and wrinkled; his hearing and sight, once sharp, grew dull. Everything about him changed: his gait became shuffling, his voice faint, his strength weakness, and his mental alertness senility.\n\nʿAbd Allāh [ibn Masʿūd] read asfala al-sāfilīn, with the definite article: “the lowest of the low.”","title":"Finest proportion and the lowest condition [IV:774]","author":"kashshaf","surah":95,"ar":"في أحسن تقويم في أحسن تعديل لشكله وصورته وتسوية لأعضائه. ثم كان عاقبة أمره حين لم يشكر نعمة تلك الخلقة الحسنة القويمة السوية: أن رددناه أسفل من سفل خلقا وتركيبا، يعنى: أقبح من قبح صورة وأشوهه خلقة، وهم أصحاب النار أو أسفل من سفل من أهل الدركات. أو ثم رددناه بعد ذلك التقويم والتحسين أسفل من سفل في حسن الصورة والشكل: حيث نكسناه في خلقه، فقوس ظهره بعد اعتداله، وابيض شعره بعد سواده، وتشنن جلده وكان بضا، وكل سمعه وبصره وكانا حديدين، وتغير كل شيء منه: فمشيه دليف ، وصوته خفات، وقوته ضعف، وشهامته خرف وقرأ عبد الله:\n\nأسفل السافلين.","html":"<p>“In the finest proportion”: in the finest adjustment of his shape and form, and the most harmonious arrangement of his limbs. Then, when he failed to give thanks for the blessing of that beautiful, upright, well-proportioned creation, his final outcome was that We returned him lower than those low in constitution and composition: uglier in form than the ugly, and most deformed in creation. These are the inhabitants of the Fire. Or: lower than the lowest inhabitants of its descending levels.</p><p>Or: after that proportioning and beautification, We returned him lower than those lowest in beauty of form and shape, reversing his constitution. His back, once straight, became bent; his hair, once black, turned white; his skin, once tender, dried and wrinkled; his hearing and sight, once sharp, grew dull. Everything about him changed: his gait became shuffling, his voice faint, his strength weakness, and his mental alertness senility.</p><p>ʿAbd Allāh <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(الله)</bdi> [ibn Masʿūd] read asfala al-sāfilīn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(السافلين)</bdi>, with the definite article: “the lowest of the low.”</p>","lemma":""},{"id":"T095.03","heading":"T095.03 — The vocabulary of ageing [XVI:506]","text":"On “dried and wrinkled,” al-Asās says: “Tashannana jilduhu min al-haram means his skin shrivelled and dried from old age. One says, ‘an old man like a worn-out waterskin.’”\n\nOn “tender,” baḍḍ, with the single-dotted bāʾ and dotted ḍād: al-Asās says: “Al-Aṣmaʿī said: abyaḍ baḍḍ means intensely white. Al-Mubarrad said: it means a person with fine skin on which everything leaves an impression. One says imraʾa ghaḍḍa baḍḍa, a fresh, tender-skinned woman.”\n\nOn “his gait became shuffling”: dalīf is slow walking. Al-Asās says: “The old man and the fettered man dalafa dalīfan wa-dulūfan; this is a little more than creeping.”\n\nOn “senility”: kharaf, with the middle consonant vowelled, means deterioration of the mind.","title":"The vocabulary of ageing [XVI:506]","author":"tibi","on":["K095.04"],"anchor":"K095.04","surah":95,"ar":"قوله: (تشنن)، الأساس: \"تشنن جلده من الهرم، أي: تشنج ويبس. ويقال: شيخ كالشن البالي\".\n\nقوله: (بضا)، بالباء الموحدة من تحت والضاد المعجمة. الأساس: \"قال الأصمعي: أبيض بض. وهو الشديد البياض. وقال المبرد: هو الرقيق البشرة الذي يؤثر فيه كل شيء. وامرأة غضة بضة\".\n\nقوله: (فمشيه دليف)، الدليف: المشي الرويد. الأساس: \"دلف الشيخ والمقيد دليفا ودلوفا، وهو فوق الدبيب\".\n\nقوله: (خرف)، الخرف بالتحريك: فساد العقل.","html":"<p>On “dried and wrinkled,” al-Asās says: “Tashannana jilduhu min al-haram <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(تشنّن جلده من الهرم)</bdi> means his skin shrivelled and dried from old age. One says, ‘an old man like a worn-out waterskin.’”</p><p>On “tender,” baḍḍ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(بَضّ)</bdi>, with the single-dotted bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> and dotted ḍād <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ضاد (ض))</bdi>: al-Asās says: “Al-Aṣmaʿī said: abyaḍ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(أبيض)</bdi> baḍḍ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(بَضّ)</bdi> means intensely white. Al-Mubarrad said: it means a person with fine skin on which everything leaves an impression. One says imraʾa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(امرأة)</bdi> ghaḍḍa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(غَضّة)</bdi> baḍḍa <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(بَضّة)</bdi>, a fresh, tender-skinned woman.”</p><p>On “his gait became shuffling”: dalīf <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(دليف)</bdi> is slow walking. Al-Asās says: “The old man and the fettered man dalafa dalīfan <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(دليفًا)</bdi> wa-dulūfan <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ودلوفًا)</bdi>; this is a little more than creeping.”</p><p>On “senility”: kharaf, with the middle consonant vowelled, means deterioration of the mind.</p>","lemma":"تشنن"}],"cairo_notes":[],"verses":[{"key":"95:4","number":4,"ar":"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ","en":"Surely We created man of the best stature"},{"key":"95:5","number":5,"ar":"ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ","en":"Then we reduced him to the lowest of the low"}],"quran_ar":"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ ﴿4﴾ ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ ﴿5﴾","quran_en":"4. Surely We created man of the best stature 5. Then we reduced him to the lowest of the low"},{"id":"K095.05","q":"95:6","s":95,"surah":"al-Tīn","surah_ar":"التين","title":"al-Tīn · The exception","cairo":"K IV:773–774 · T XVI:504–508","source_page_first":773,"source_page_last":774,"chunk":"passages-095","segments":[{"type":"exposition","title":"The exception [IV:774]","html":"<p>If you ask how the exception works on the two interpretations, I answer: on the first it is a connected exception, and its connection is plain. On the second it is disconnected: “But those among the aged who were righteous have an abiding, uninterrupted reward”—for their obedience, their patience under God’s trial of old age and decrepitude, their endurance of hardships, and their continuing to worship despite their faltering ability to rise.</p>","author":"kashshaf","source_id":"K095.05"},{"type":"exposition","title":"The two interpretations and the exception [XVI:506–507]","html":"<p>On “how does the exception work on the two interpretations?”: someone has taken this to mean the Ḥijāzī and Tamīmī grammatical schools. That is not correct. It means the two interpretations just mentioned, as the answer and the introductory fāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(فاء (ف))</bdi> in the question show.</p><p>On “on the first it is a connected exception”: that is, when being returned to “the lowest of the low” means being returned lower than those low in constitution and composition, namely the inhabitants of the Fire, or lower than the lowest inhabitants of its descending levels. Al-Wāḥidī reports from Mujāhid: “‘Then We returned him’ to the Fire. The Fire is the lowest of the low because Jahannam has levels one beneath another. He then makes the exception, ‘except those who believe and do righteous deeds’: these are not returned to the Fire.”</p><p>On “on the second it is disconnected”: that is, when “the lowest of the low” means being returned lower than those lowest in beauty of form and shape. Hence he says: “But those among the aged who were righteous have an abiding reward.”</p>","author":"tibi","source_id":"T095.04"}],"types":["exposition","language","theology","reports"],"ar":"فإن قلت: فكيف الاستثناء على المذهبين؟ قلت: هو على الأول متصل ظاهر الاتصال، وعلى الثاني منقطع. يعنى: ولكن الذين كانوا صالحين من الهرمى فلهم ثواب دائم غير منقطع على طاعتهم وصبرهم على ابتلاء الله بالشيخوخة والهرم، وعلى مقاساة المشاق والقيام بالعبادة على تخاذل نهوضهم.\nقوله: (فكيف الاستثناء على المذهبين)، عن بعضهم: أراد الحجازية والتميمية وليس بذلك، بل على الوجهين المذكورين كما ينبئ عنه الجواب ودخول الفاء في السؤال.\nقوله: (هو على الأول متصل)، أي على أن يراد بالرد إلى أسفل سافلين، الرد إلى أسفل من سفل خلقا وتركيبا، وهم أصحاب النار، أو أسفل من سفل من أهل الدركات. قال الواحدي عن مجاهد: \"ثم رددناه إلى النار، والنار أسفل سافلين، لأنه جهنم بعضها أسفل من بعض، ثم استثنى {إلا الذين آمنوا وعملوا الصالحات}، أي: إلا هؤلاء، فإنهم لا يردون إلى النار\".\nقوله: (وعلى الثاني منقطع)، أي على أن يراد ب \"أسفل سافلين\"، الرد إلى أسفل من سفل في حسن الصورة والشكل، ولذلك قال: \"لكن الذين كانوا صالحين من الهرمى، فلهم ثواب دائم\".","layers":[{"id":"K095.05","heading":"K095.05 — The exception [IV:774]","text":"If you ask how the exception works on the two interpretations, I answer: on the first it is a connected exception, and its connection is plain. On the second it is disconnected: “But those among the aged who were righteous have an abiding, uninterrupted reward”—for their obedience, their patience under God’s trial of old age and decrepitude, their endurance of hardships, and their continuing to worship despite their faltering ability to rise.","title":"The exception [IV:774]","author":"kashshaf","surah":95,"ar":"فإن قلت: فكيف الاستثناء على المذهبين؟ قلت: هو على الأول متصل ظاهر الاتصال، وعلى الثاني منقطع. يعنى: ولكن الذين كانوا صالحين من الهرمى فلهم ثواب دائم غير منقطع على طاعتهم وصبرهم على ابتلاء الله بالشيخوخة والهرم، وعلى مقاساة المشاق والقيام بالعبادة على تخاذل نهوضهم.","html":"<p>If you ask how the exception works on the two interpretations, I answer: on the first it is a connected exception, and its connection is plain. On the second it is disconnected: “But those among the aged who were righteous have an abiding, uninterrupted reward”—for their obedience, their patience under God’s trial of old age and decrepitude, their endurance of hardships, and their continuing to worship despite their faltering ability to rise.</p>","lemma":""},{"id":"T095.04","heading":"T095.04 — The two interpretations and the exception [XVI:506–507]","text":"On “how does the exception work on the two interpretations?”: someone has taken this to mean the Ḥijāzī and Tamīmī grammatical schools. That is not correct. It means the two interpretations just mentioned, as the answer and the introductory fāʾ in the question show.\n\nOn “on the first it is a connected exception”: that is, when being returned to “the lowest of the low” means being returned lower than those low in constitution and composition, namely the inhabitants of the Fire, or lower than the lowest inhabitants of its descending levels. Al-Wāḥidī reports from Mujāhid: “‘Then We returned him’ to the Fire. The Fire is the lowest of the low because Jahannam has levels one beneath another. He then makes the exception, ‘except those who believe and do righteous deeds’: these are not returned to the Fire.”\n\nOn “on the second it is disconnected”: that is, when “the lowest of the low” means being returned lower than those lowest in beauty of form and shape. Hence he says: “But those among the aged who were righteous have an abiding reward.”","title":"The two interpretations and the exception [XVI:506–507]","author":"tibi","on":["K095.05"],"anchor":"K095.05","surah":95,"ar":"قوله: (فكيف الاستثناء على المذهبين)، عن بعضهم: أراد الحجازية والتميمية وليس بذلك، بل على الوجهين المذكورين كما ينبئ عنه الجواب ودخول الفاء في السؤال.\n\nقوله: (هو على الأول متصل)، أي على أن يراد بالرد إلى أسفل سافلين، الرد إلى أسفل من سفل خلقا وتركيبا، وهم أصحاب النار، أو أسفل من سفل من أهل الدركات. قال الواحدي عن مجاهد: \"ثم رددناه إلى النار، والنار أسفل سافلين، لأنه جهنم بعضها أسفل من بعض، ثم استثنى {إلا الذين آمنوا وعملوا الصالحات}، أي: إلا هؤلاء، فإنهم لا يردون إلى النار\".\n\nقوله: (وعلى الثاني منقطع)، أي على أن يراد ب \"أسفل سافلين\"، الرد إلى أسفل من سفل في حسن الصورة والشكل، ولذلك قال: \"لكن الذين كانوا صالحين من الهرمى، فلهم ثواب دائم\".","html":"<p>On “how does the exception work on the two interpretations?”: someone has taken this to mean the Ḥijāzī and Tamīmī grammatical schools. That is not correct. It means the two interpretations just mentioned, as the answer and the introductory fāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(فاء (ف))</bdi> in the question show.</p><p>On “on the first it is a connected exception”: that is, when being returned to “the lowest of the low” means being returned lower than those low in constitution and composition, namely the inhabitants of the Fire, or lower than the lowest inhabitants of its descending levels. Al-Wāḥidī reports from Mujāhid: “‘Then We returned him’ to the Fire. The Fire is the lowest of the low because Jahannam has levels one beneath another. He then makes the exception, ‘except those who believe and do righteous deeds’: these are not returned to the Fire.”</p><p>On “on the second it is disconnected”: that is, when “the lowest of the low” means being returned lower than those lowest in beauty of form and shape. Hence he says: “But those among the aged who were righteous have an abiding reward.”</p>","lemma":"فكيف الاستثناء على المذهبين"}],"cairo_notes":[],"verses":[{"key":"95:6","number":6,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ","en":"Save those who believe and do good works, and theirs is a reward unfailing"}],"quran_ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ ﴿6﴾","quran_en":"6. Save those who believe and do good works, and theirs is a reward unfailing"},{"id":"K095.06","q":"95:7–8","s":95,"surah":"al-Tīn","surah_ar":"التين","title":"al-Tīn · Who is addressed, and what makes him a denier?","cairo":"K IV:773–774 · T XVI:504–508","source_page_first":773,"source_page_last":774,"chunk":"passages-095","segments":[{"type":"exposition","title":"Who is addressed, and what makes him a denier? [IV:774–775]","html":"<p>If you ask who is addressed by “So what makes you deny?”, I answer: the human being is addressed through a shift of person. That is: what makes you a liar on account of the requital and your denial of it after this proof? You lie when you deny recompense, because everyone who denies the truth is a liar. What, then, compels you to become a liar through denying recompense? The bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> is like that in His saying, “those who take him as their patron and those who, because of him, associate others [with God]” [16:100].</p><p>The meaning is that you can see no clearer proof of the Creator’s power than the human being’s creation from a drop, his proportioning as a well-formed human, his gradual progress through stages of growth until he reaches maturity and full stature, and then his reversal until he reaches the most abject age. Whoever has power to do all this with the human being is not incapable of bringing him back. So what, human being, is the cause of your denying recompense after this decisive proof?</p><p>It is also said that the address is to God’s Messenger.</p><p>“Is God not the wisest of judges?” is a threat to the unbelievers: He will judge them as they deserve. It is related from the Prophet that, when he recited it, he said: “Indeed; and I am among those who bear witness to that.”</p>","author":"kashshaf","source_id":"K095.06"},{"type":"exposition","title":"The causal bāʾ [XVI:507]","html":"<p>On “‘those who, because of him, associate others’ [16:100]”: that is, because of Satan they associate others with God. The bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> in bihi <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(به)</bdi> is not the complement of mushrikūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(مشركون)</bdi>, “associating others”; its proper complement is omitted.</p>","author":"tibi","source_id":"T095.05"},{"type":"exposition","title":"The alternative addressee and the force of the question [XVI:508]","html":"<p>On “it is also said that the address is to God’s Messenger”: this is coordinated with “the human being is addressed.” On this interpretation there is no shift of person, and mā <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ما)</bdi> has the sense of man, “who”: who, then, calls you a liar, truthful and confirmed Messenger, regarding the true religion you have brought—or on account of religion—after the appearance of these proofs indicating your prophethood? “Is God not the wisest of judges?” He will judge between you and those who deny you.</p><p>If the address is taken to concern the human being, one should adopt the interpretation involving a shift of person, because of the preceding “We have indeed created the human being in the finest proportion,” and take the bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> as causal, since the human being is himself the denier. The meaning is: “Human being, what drives you to be a liar through denying recompense?” The expression both conveys wonder and arouses it. Having established that He created the human being in the finest proportion and then returned him to the most abject age, God has indicated the perfection of His power to originate and restore. He then asks why the human being denies recompense, because the cause of something wondered at is obscure. This is, as you see, manifest and clear. It is indicated by his saying, “So what, human being, is the cause of your denying recompense after this decisive proof?” On this interpretation, “Is God not the wisest of judges?” threatens the unbelievers, declaring that He judges them as they deserve.</p>","author":"tibi","source_id":"T095.06"},{"type":"exposition","title":"The response to the final verse [XVI:508]","html":"<p>On “he said, ‘Indeed; and I am among those who bear witness to that’”: the report is transmitted by al-Tirmidhī and Abū Dāwūd from Abū Hurayra, who said that God’s Messenger said: “Whoever among you recites ‘By the fig and the olive,’ and reaches ‘Is God not the wisest of judges?’, should say: ‘Indeed; and I am among those who bear witness to that.’”</p><p>End of the sūrah.</p>","author":"tibi","source_id":"T095.07"}],"types":["exposition","language","theology","reports"],"ar":"فإن قلت: فما يكذبك من المخاطب به؟ قلت: هو خطاب للإنسان على طريقة الالتفات، أى: فما يجعلك كاذبا بسبب الدين وإنكاره بعد هذا الدليل، يعنى أنك تكذب إذا كذبت بالجزاء، لأن كل مكذب بالحق فهو كاذب، فأى شيء يضطرك إلى أن تكون كاذبا بسبب تكذيب الجزاء. والباء مثلها في قوله تعالى الذين يتولونه والذين هم به مشركون والمعنى: أن خلق الإنسان من نطفة، وتقويمه بشرا سويا وتدريجه في مراتب الزيادة إلى أن يكمل ويستوي، ثم تنكيسه إلى أن يبلغ أرذل العمر: لا ترى دليلا أوضح منه على قدرة الخالق، وأن من قدر من الإنسان على هذا كله: لم يعجز عن إعادته، فما سبب تكذيبك أيها الإنسان بالجزاء بعد هذا الدليل القاطع. وقيل: الخطاب لرسول الله صلى الله عليه وسلم أليس الله بأحكم الحاكمين وعيد للكفار، وأنه يحكم عليهم بما هم \nأهله. وعن النبي صلى الله عليه وسلم: أنه كان إذا قرأها قال: «بلى وأنا على ذلك من الشاهدين» .\nقوله: ({والذين هم به مشركون} [النحل: 100])، أي: بسبب الشيطان يشركون بالله. والباء في {بهي} ليست بصلة {مشركون}، بل صلته محذوفة.\nقوله: (وقيل: الخطاب لرسول الله? )، عطف على قوله: \"هو خطاب للإنسان\"، وعلى هذا لا يكون في الكلام التفات، وتكون \"ما\" بمعنى \"من\"، أي: فمن يكذبك أيها الرسول الصادق المصدق، بما جئت به من الدين الحق، أو بسبب الدين بعد ظهور هذه الدلائل الدالة على نبوتك؟ أليس الله بأحكم الحاكمين؟ يحكم بينك وبين أهل التكذيب. وإذا قيل: إن الخطاب للإنسان، ينبغي أن يذهب إلى الالتفات، لما سبق من قوله: {لقد خلقنا الإنسان في أحسن تقويم}، ويجعل الباء للتسبيب، لأن الإنسان هو المكذب، والمعنى: أيها الإنسان، ما الذي يلجئك إلى أن تكون كاذبا بسبب تكذيب الجزاء. وفي الكلام تعجب وتعجيب؛ وذلك أنه تعالى لما قرر أنه خلق الإنسان في أحسن تقويم، ثم رده إلى أرذل العمر، دل على كمال قدرته على الإنشاء والإعادة، فسأل بعد ذلك عن سبب تكذيب الإنسان بالجزاء، لأن ما يتعجب منه يخفي سببه، وهذا كما ترى ظاهر جلي، وإليه الإشارة بقوله: \"فما سبب تكذيبك أيها الإنسان بالجزاء، بعد هذا الدليل القاطع؟ \"، وعلى هذا قوله: {أليس الله بأحكم الحاكمين}، وعيد للكفار، وأنه يحكم عليهم بما هو أهله.\nقوله: (قال: \"بلى وأنا على ذلك من الشاهدين\")، الحديث من رواية الترمذي وأبي داود، عن أبي هريرة قال: قال رسول الله? : \"من قرأ منكم {والتين والزيتون}، فانتهى إلى قوله: {أليس الله بأحكم الحاكمين}، فليقل: بلى وأنا على ذلك من الشاهدين\".\nتمت السورة","layers":[{"id":"K095.06","heading":"K095.06 — Who is addressed, and what makes him a denier? [IV:774–775]","text":"If you ask who is addressed by “So what makes you deny?”, I answer: the human being is addressed through a shift of person. That is: what makes you a liar on account of the requital and your denial of it after this proof? You lie when you deny recompense, because everyone who denies the truth is a liar. What, then, compels you to become a liar through denying recompense? The bāʾ is like that in His saying, “those who take him as their patron and those who, because of him, associate others [with God]” [16:100].\n\nThe meaning is that you can see no clearer proof of the Creator’s power than the human being’s creation from a drop, his proportioning as a well-formed human, his gradual progress through stages of growth until he reaches maturity and full stature, and then his reversal until he reaches the most abject age. Whoever has power to do all this with the human being is not incapable of bringing him back. So what, human being, is the cause of your denying recompense after this decisive proof?\n\nIt is also said that the address is to God’s Messenger.\n\n“Is God not the wisest of judges?” is a threat to the unbelievers: He will judge them as they deserve. It is related from the Prophet that, when he recited it, he said: “Indeed; and I am among those who bear witness to that.”","title":"Who is addressed, and what makes him a denier? [IV:774–775]","author":"kashshaf","surah":95,"ar":"فإن قلت: فما يكذبك من المخاطب به؟ قلت: هو خطاب للإنسان على طريقة الالتفات، أى: فما يجعلك كاذبا بسبب الدين وإنكاره بعد هذا الدليل، يعنى أنك تكذب إذا كذبت بالجزاء، لأن كل مكذب بالحق فهو كاذب، فأى شيء يضطرك إلى أن تكون كاذبا بسبب تكذيب الجزاء. والباء مثلها في قوله تعالى الذين يتولونه والذين هم به مشركون والمعنى: أن خلق الإنسان من نطفة، وتقويمه بشرا سويا وتدريجه في مراتب الزيادة إلى أن يكمل ويستوي، ثم تنكيسه إلى أن يبلغ أرذل العمر: لا ترى دليلا أوضح منه على قدرة الخالق، وأن من قدر من الإنسان على هذا كله: لم يعجز عن إعادته، فما سبب تكذيبك أيها الإنسان بالجزاء بعد هذا الدليل القاطع. وقيل: الخطاب لرسول الله صلى الله عليه وسلم أليس الله بأحكم الحاكمين وعيد للكفار، وأنه يحكم عليهم بما هم \n\nأهله. وعن النبي صلى الله عليه وسلم: أنه كان إذا قرأها قال: «بلى وأنا على ذلك من الشاهدين» .","html":"<p>If you ask who is addressed by “So what makes you deny?”, I answer: the human being is addressed through a shift of person. That is: what makes you a liar on account of the requital and your denial of it after this proof? You lie when you deny recompense, because everyone who denies the truth is a liar. What, then, compels you to become a liar through denying recompense? The bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> is like that in His saying, “those who take him as their patron and those who, because of him, associate others [with God]” [16:100].</p><p>The meaning is that you can see no clearer proof of the Creator’s power than the human being’s creation from a drop, his proportioning as a well-formed human, his gradual progress through stages of growth until he reaches maturity and full stature, and then his reversal until he reaches the most abject age. Whoever has power to do all this with the human being is not incapable of bringing him back. So what, human being, is the cause of your denying recompense after this decisive proof?</p><p>It is also said that the address is to God’s Messenger.</p><p>“Is God not the wisest of judges?” is a threat to the unbelievers: He will judge them as they deserve. It is related from the Prophet that, when he recited it, he said: “Indeed; and I am among those who bear witness to that.”</p>","lemma":""},{"id":"T095.05","heading":"T095.05 — The causal bāʾ [XVI:507]","text":"On “‘those who, because of him, associate others’ [16:100]”: that is, because of Satan they associate others with God. The bāʾ in bihi is not the complement of mushrikūn, “associating others”; its proper complement is omitted.","title":"The causal bāʾ [XVI:507]","author":"tibi","on":["K095.06"],"anchor":"K095.06","surah":95,"ar":"قوله: ({والذين هم به مشركون} [النحل: 100])، أي: بسبب الشيطان يشركون بالله. والباء في {بهي} ليست بصلة {مشركون}، بل صلته محذوفة.","html":"<p>On “‘those who, because of him, associate others’ [16:100]”: that is, because of Satan they associate others with God. The bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> in bihi <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(به)</bdi> is not the complement of mushrikūn <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(مشركون)</bdi>, “associating others”; its proper complement is omitted.</p>","lemma":"{والذين هم به مشركون"},{"id":"T095.06","heading":"T095.06 — The alternative addressee and the force of the question [XVI:508]","text":"On “it is also said that the address is to God’s Messenger”: this is coordinated with “the human being is addressed.” On this interpretation there is no shift of person, and mā has the sense of man, “who”: who, then, calls you a liar, truthful and confirmed Messenger, regarding the true religion you have brought—or on account of religion—after the appearance of these proofs indicating your prophethood? “Is God not the wisest of judges?” He will judge between you and those who deny you.\n\nIf the address is taken to concern the human being, one should adopt the interpretation involving a shift of person, because of the preceding “We have indeed created the human being in the finest proportion,” and take the bāʾ as causal, since the human being is himself the denier. The meaning is: “Human being, what drives you to be a liar through denying recompense?” The expression both conveys wonder and arouses it. Having established that He created the human being in the finest proportion and then returned him to the most abject age, God has indicated the perfection of His power to originate and restore. He then asks why the human being denies recompense, because the cause of something wondered at is obscure. This is, as you see, manifest and clear. It is indicated by his saying, “So what, human being, is the cause of your denying recompense after this decisive proof?” On this interpretation, “Is God not the wisest of judges?” threatens the unbelievers, declaring that He judges them as they deserve.","title":"The alternative addressee and the force of the question [XVI:508]","author":"tibi","on":["K095.06"],"anchor":"K095.06","surah":95,"ar":"قوله: (وقيل: الخطاب لرسول الله? )، عطف على قوله: \"هو خطاب للإنسان\"، وعلى هذا لا يكون في الكلام التفات، وتكون \"ما\" بمعنى \"من\"، أي: فمن يكذبك أيها الرسول الصادق المصدق، بما جئت به من الدين الحق، أو بسبب الدين بعد ظهور هذه الدلائل الدالة على نبوتك؟ أليس الله بأحكم الحاكمين؟ يحكم بينك وبين أهل التكذيب. وإذا قيل: إن الخطاب للإنسان، ينبغي أن يذهب إلى الالتفات، لما سبق من قوله: {لقد خلقنا الإنسان في أحسن تقويم}، ويجعل الباء للتسبيب، لأن الإنسان هو المكذب، والمعنى: أيها الإنسان، ما الذي يلجئك إلى أن تكون كاذبا بسبب تكذيب الجزاء. وفي الكلام تعجب وتعجيب؛ وذلك أنه تعالى لما قرر أنه خلق الإنسان في أحسن تقويم، ثم رده إلى أرذل العمر، دل على كمال قدرته على الإنشاء والإعادة، فسأل بعد ذلك عن سبب تكذيب الإنسان بالجزاء، لأن ما يتعجب منه يخفي سببه، وهذا كما ترى ظاهر جلي، وإليه الإشارة بقوله: \"فما سبب تكذيبك أيها الإنسان بالجزاء، بعد هذا الدليل القاطع؟ \"، وعلى هذا قوله: {أليس الله بأحكم الحاكمين}، وعيد للكفار، وأنه يحكم عليهم بما هو أهله.","html":"<p>On “it is also said that the address is to God’s Messenger”: this is coordinated with “the human being is addressed.” On this interpretation there is no shift of person, and mā <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(ما)</bdi> has the sense of man, “who”: who, then, calls you a liar, truthful and confirmed Messenger, regarding the true religion you have brought—or on account of religion—after the appearance of these proofs indicating your prophethood? “Is God not the wisest of judges?” He will judge between you and those who deny you.</p><p>If the address is taken to concern the human being, one should adopt the interpretation involving a shift of person, because of the preceding “We have indeed created the human being in the finest proportion,” and take the bāʾ <bdi class=\"ar-term\" lang=\"ar\" dir=\"rtl\">(باء (ب))</bdi> as causal, since the human being is himself the denier. The meaning is: “Human being, what drives you to be a liar through denying recompense?” The expression both conveys wonder and arouses it. Having established that He created the human being in the finest proportion and then returned him to the most abject age, God has indicated the perfection of His power to originate and restore. He then asks why the human being denies recompense, because the cause of something wondered at is obscure. This is, as you see, manifest and clear. It is indicated by his saying, “So what, human being, is the cause of your denying recompense after this decisive proof?” On this interpretation, “Is God not the wisest of judges?” threatens the unbelievers, declaring that He judges them as they deserve.</p>","lemma":"وقيل: الخطاب لرسول الله? "},{"id":"T095.07","heading":"T095.07 — The response to the final verse [XVI:508]","text":"On “he said, ‘Indeed; and I am among those who bear witness to that’”: the report is transmitted by al-Tirmidhī and Abū Dāwūd from Abū Hurayra, who said that God’s Messenger said: “Whoever among you recites ‘By the fig and the olive,’ and reaches ‘Is God not the wisest of judges?’, should say: ‘Indeed; and I am among those who bear witness to that.’”\n\nEnd of the sūrah.","title":"The response to the final verse [XVI:508]","author":"tibi","on":["K095.06"],"anchor":"K095.06","surah":95,"ar":"قوله: (قال: \"بلى وأنا على ذلك من الشاهدين\")، الحديث من رواية الترمذي وأبي داود، عن أبي هريرة قال: قال رسول الله? : \"من قرأ منكم {والتين والزيتون}، فانتهى إلى قوله: {أليس الله بأحكم الحاكمين}، فليقل: بلى وأنا على ذلك من الشاهدين\".\n\nتمت السورة","html":"<p>On “he said, ‘Indeed; and I am among those who bear witness to that’”: the report is transmitted by al-Tirmidhī and Abū Dāwūd from Abū Hurayra, who said that God’s Messenger said: “Whoever among you recites ‘By the fig and the olive,’ and reaches ‘Is God not the wisest of judges?’, should say: ‘Indeed; and I am among those who bear witness to that.’”</p><p>End of the sūrah.</p>","lemma":"قال: \"بلى وأنا على ذلك من الشاهدين\""}],"cairo_notes":[],"verses":[{"key":"95:7","number":7,"ar":"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","en":"So who henceforth will give the lie to thee about the judgment"},{"key":"95:8","number":8,"ar":"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ","en":"Is not Allah the most conclusive of all judges"}],"quran_ar":"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ ﴿7﴾ أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ ﴿8﴾","quran_en":"7. So who henceforth will give the lie to thee about the judgment 8. Is not Allah the most conclusive of all judges"},{"id":"K095.07","q":"95:1–8","s":95,"surah":"al-Tīn","surah_ar":"التين","title":"al-Tīn · Closing report","cairo":"K IV:773–774 · T XVI:504–508","source_page_first":773,"source_page_last":774,"chunk":"passages-095","segments":[{"type":"exposition","title":"Closing report [IV:775]","html":"<p>From God’s Messenger: “Whoever recites Sūrat ‘By the fig,’ God gives him two qualities: well-being and certainty as long as he remains in this world; and when he dies, God gives him a reward according to the number of those who have recited this sūrah.”</p>","author":"kashshaf","source_id":"K095.07"}],"types":["exposition","language","theology","reports"],"ar":"عن رسول الله صلى الله عليه وسلم: «من قرأ سورة والتين أعطاه الله خصلتين: العافية واليقين ما دام في دار الدنيا، وإذا مات أعطاه الله من الأجر بعدد من قرأ هذه السورة» .","layers":[{"id":"K095.07","heading":"K095.07 — Closing report [IV:775]","text":"From God’s Messenger: “Whoever recites Sūrat ‘By the fig,’ God gives him two qualities: well-being and certainty as long as he remains in this world; and when he dies, God gives him a reward according to the number of those who have recited this sūrah.”","title":"Closing report [IV:775]","author":"kashshaf","surah":95,"ar":"عن رسول الله صلى الله عليه وسلم: «من قرأ سورة والتين أعطاه الله خصلتين: العافية واليقين ما دام في دار الدنيا، وإذا مات أعطاه الله من الأجر بعدد من قرأ هذه السورة» .","html":"<p>From God’s Messenger: “Whoever recites Sūrat ‘By the fig,’ God gives him two qualities: well-being and certainty as long as he remains in this world; and when he dies, God gives him a reward according to the number of those who have recited this sūrah.”</p>","lemma":""}],"cairo_notes":[],"verses":[{"key":"95:1","number":1,"ar":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ","en":"By the fig and the olive"},{"key":"95:2","number":2,"ar":"وَطُورِ سِينِينَ","en":"By Mount Sinai"},{"key":"95:3","number":3,"ar":"وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","en":"And by this land made safe"},{"key":"95:4","number":4,"ar":"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ","en":"Surely We created man of the best stature"},{"key":"95:5","number":5,"ar":"ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ","en":"Then we reduced him to the lowest of the low"},{"key":"95:6","number":6,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ","en":"Save those who believe and do good works, and theirs is a reward unfailing"},{"key":"95:7","number":7,"ar":"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","en":"So who henceforth will give the lie to thee about the judgment"},{"key":"95:8","number":8,"ar":"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ","en":"Is not Allah the most conclusive of all judges"}],"quran_ar":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ ﴿1﴾ وَطُورِ سِينِينَ ﴿2﴾ وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ ﴿3﴾ لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ ﴿4﴾ ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ ﴿5﴾ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ ﴿6﴾ فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ ﴿7﴾ أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ ﴿8﴾","quran_en":"1. By the fig and the olive 2. By Mount Sinai 3. And by this land made safe 4. Surely We created man of the best stature 5. Then we reduced him to the lowest of the low 6. Save those who believe and do good works, and theirs is a reward unfailing 7. So who henceforth will give the lie to thee about the judgment 8. Is not Allah the most conclusive of all judges"}];
